// lib/i18n.js — tiny translation layer for the authenticated app (EN/RO/RU/UK).
// Language is a per-company setting (companies.lang). Server components read
// co.lang and call t(key, lang); client components receive lang as a prop.
//
//   t("nav_dashboard", "ro")            -> "Panou"
//   t("kpi_saveNet", "en", { x: "€40" }) -> "You save €40/month from day one"
//
// Missing keys fall back to English, then to the key itself — nothing crashes.

