  prop_refreshing:      { en: "Refreshing…", ro: "Se actualizează…", ru: "Обновление…", uk: "Оновлення…" },
  prop_refreshed:       { en: "Updated, the client will see the latest version next time they open it.", ro: "Actualizat, clientul va vedea ultima versiune data viitoare când deschide linkul.", ru: "Обновлено, клиент увидит последнюю версию при следующем открытии.", uk: "Оновлено, клієнт побачить останню версію під час наступного відкриття." },
  prop_refresh_accepted: { en: "Already accepted by the client, the link stays frozen to protect what they agreed to.", ro: "Deja acceptată de client, linkul rămâne fix pentru a proteja ce a fost agreat.", ru: "Уже принято клиентом, ссылка остаётся неизменной, чтобы защитить согласованные условия.", uk: "Уже прийнято клієнтом, посилання лишається незмінним, щоб захистити погоджені умови." },
