  // Ukraine's file (lib/uaGrid.js)
  cat_ua_duty:    { en: "Ukraine: solar panels and lithium batteries over 300 W and 100 Ah are imported without import duty or VAT until 1 January 2029. Mounting structures pay the full 20% VAT. For inverters the customs code decides, so check with your broker.", ro: "Ucraina: panourile solare și bateriile cu litiu de peste 300 W și 100 Ah intră fără taxă vamală și fără TVA până la 1 ianuarie 2029. Structurile de montaj plătesc TVA-ul întreg de 20%. La invertoare decide codul vamal, așa că întreabă brokerul.", ru: "Украина: солнечные панели и литиевые батареи мощнее 300 Вт и ёмкостью больше 100 А·ч ввозятся без пошлины и НДС до 1 января 2029 года. Монтажные конструкции облагаются полным НДС 20%. Для инверторов всё решает таможенный код, уточните у брокера.", uk: "Україна: сонячні панелі та літієві батареї потужністю понад 300 Вт і ємністю понад 100 А·год ввозяться без мита та ПДВ до 1 січня 2029 року. Монтажні конструкції обкладаються повним ПДВ 20%. Для інверторів усе вирішує митний код, уточніть у брокера." },
  save_needs_ua_db: { en: "Not saved: Ukraine needs the database update (supabase/add-ukrainian.sql)", ro: "Nesalvat: Ucraina cere actualizarea bazei de date (supabase/add-ukrainian.sql)", ru: "Не сохранено: для Украины нужно обновить базу данных (supabase/add-ukrainian.sql)", uk: "Не збережено: для України потрібно оновити базу даних (supabase/add-ukrainian.sql)" },
  saved_device:   { en: "Saved on this device", ro: "Salvat pe acest dispozitiv", ru: "Сохранено на этом устройстве", uk: "Збережено на цьому пристрої" },
  offline_bar:    { en: "No signal. Pages show the last copy saved on this device, and quote edits save when the signal is back.", ro: "Fără semnal. Paginile arată ultima copie salvată pe acest dispozitiv, iar modificările ofertelor se salvează când revine semnalul.", ru: "Нет сети. Страницы показывают последнюю копию, сохранённую на этом устройстве, а правки расчётов сохранятся, когда появится связь.", uk: "Немає мережі. Сторінки показують останню копію, збережену на цьому пристрої, а зміни в розрахунках збережуться, коли з’явиться зв’язок." },
